/**
 * Site Navigation -- section behaviour.
 *
 * GENERATED by tools/uew from shared/section-00-nav.html. Do not edit by hand.
 *
 * The section's original script bodies are reproduced verbatim inside
 * uewRun(). What is added around them is the Elementor lifecycle: widgets are
 * injected into the editor canvas long after DOMContentLoaded, so a bare IIFE
 * would query an element that does not exist yet and the section would look
 * "broken" in the editor. Registering on frontend/element_ready fixes that, and
 * the data-uew-ready latch keeps a double call harmless.
 */
( function () {
	'use strict';

	var ROOT_SELECTOR = "#umoyaSiteNavMount";
	var WIDGET_NAME = "umoya-site-nav";

	function uewRun() {
		(function(){
		      'use strict';

		      var bar = document.getElementById('umoyaSiteNav');
		      if (!bar || bar.dataset.ready === 'true') return;
		      bar.dataset.ready = 'true';

		      /*
		        THEME-HEADER TAKEOVER — see the CSS note at the top of this file.
		        Marks the Tevily theme header that CONTAINS this nav, so the two
		        override rules apply only there. On Elementor Canvas pages there
		        is no theme header and this simply does nothing.
		        Walks up manually instead of using closest() for max compatibility.
		      */
		      (function markThemeHeader(){
		        var node = bar.parentNode;
		        while (node && node.nodeType === 1) {
		          if (String(node.className || '').indexOf('wp-site-header') !== -1) {
		            node.className += ' umoya-nav-takeover';
		            return;
		          }
		          node = node.parentNode;
		        }
		      }());

		      var burger = bar.querySelector('.umoya-nav-burger');
		      var dropdown = bar.querySelector('.umoya-nav-dropdown');

		      function openMenu() {
		        bar.classList.add('is-open');
		        dropdown.classList.add('is-open');
		        burger.setAttribute('aria-expanded', 'true');
		        burger.setAttribute('aria-label', 'Close navigation menu');
		      }

		      function closeMenu() {
		        bar.classList.remove('is-open');
		        dropdown.classList.remove('is-open');
		        burger.setAttribute('aria-expanded', 'false');
		        burger.setAttribute('aria-label', 'Open navigation menu');
		      }

		      if (burger) {
		        burger.addEventListener('click', function() {
		          bar.classList.contains('is-open') ? closeMenu() : openMenu();
		        });
		      }

		      if (dropdown) {
		        dropdown.querySelectorAll('a').forEach(function(a) {
		          a.addEventListener('click', closeMenu);
		        });
		      }

		      document.addEventListener('click', function(event) {
		        if (!bar.contains(event.target)) closeMenu();
		      });

		      document.addEventListener('keydown', function(event) {
		        if (event.key === 'Escape') closeMenu();
		      });

		      /* Mark the current page's link active by matching the pathname.
		         Works for /for-groups, /for-groups/, and any deeper child path. */
		      var here = window.location.pathname.replace(/\/+$/, '').toLowerCase();
		      bar.querySelectorAll('[data-path]').forEach(function(item) {
		        var p = (item.getAttribute('data-path') || '').replace(/\/+$/, '').toLowerCase();
		        if (p && (here === p || here.indexOf(p + '/') === 0)) {
		          item.classList.add('is-active');
		        }
		      });

		      /* ── DOCK / STICK / HIDE-ON-SCROLL ──────────────────────────
		         Three states:
		           1. Docked  — at the top of the page the bar sits in normal flow
		                        inside the reserved space, stacked ABOVE the hero.
		           2. Stuck   — scrolled past the bar: it detaches and floats, and
		                        hides on a downward scroll.
		           3. Recalled— any upward scroll slides it straight back in.
		         The mount reserves the bar's height at all times, so detaching
		         never shifts the layout.                                        */
		      var mount = document.getElementById('umoyaSiteNavMount');
		      var stuck = false;
		      var hidden = false;
		      var lastY = window.pageYOffset || document.documentElement.scrollTop || 0;
		      var ticking = false;
		      var JITTER = 5;   /* ignore sub-5px wobble (trackpads, iOS rubber-band) */

		      function navHeight() {
		        return (mount && mount.offsetHeight) || bar.offsetHeight || 64;
		      }

		      /* Applies a class change without animating it (used when crossing
		         between docked and stuck, which should never look like a slide). */
		      function withoutAnimation(fn) {
		        bar.classList.add('no-anim');
		        fn();
		        /* Force a reflow so the browser commits the state, then re-enable. */
		        void bar.offsetHeight;
		        window.requestAnimationFrame(function() {
		          bar.classList.remove('no-anim');
		        });
		      }

		      function setStuck(next) {
		        if (stuck === next) return;
		        stuck = next;
		        bar.classList.toggle('is-stuck', next);
		      }

		      function setHidden(next) {
		        /* Never hide the bar while the mobile menu is open. */
		        if (next && bar.classList.contains('is-open')) next = false;
		        if (hidden === next) return;
		        hidden = next;
		        bar.classList.toggle('is-hidden', next);
		      }

		      function onScroll() {
		        ticking = false;
		        var y = window.pageYOffset || document.documentElement.scrollTop || 0;
		        if (y < 0) y = 0;                       /* iOS overscroll */
		        var goingDown = y > lastY;
		        var moved = Math.abs(y - lastY);

		        if (y <= navHeight()) {
		          /* Top zone — return to the docked, in-flow state. */
		          if (stuck) {
		            withoutAnimation(function() {
		              setHidden(false);
		              setStuck(false);
		            });
		          }
		        } else if (!stuck) {
		          /* Crossing into the stuck state. If that happened while scrolling
		             down, start already hidden so the bar doesn't flash into view. */
		          withoutAnimation(function() {
		            setStuck(true);
		            setHidden(goingDown);
		          });
		        } else if (moved > JITTER) {
		          setHidden(goingDown);
		        }

		        lastY = y;
		      }

		      /*
		        rAF throttles the handler to one run per frame. The setTimeout is a
		        safety net: a backgrounded or non-compositing tab never runs its rAF
		        callbacks, which would otherwise leave `ticking` latched true and
		        silently kill every future scroll update. `runScrollUpdate` is
		        guarded so whichever fires first wins and the other is a no-op.
		      */
		      function runScrollUpdate() {
		        if (!ticking) return;
		        ticking = false;
		        onScroll();
		      }

		      function requestScrollUpdate() {
		        if (ticking) return;
		        ticking = true;
		        window.requestAnimationFrame(runScrollUpdate);
		        window.setTimeout(runScrollUpdate, 200);
		      }

		      window.addEventListener('scroll', requestScrollUpdate, { passive: true });
		      window.addEventListener('resize', requestScrollUpdate);
		      /* Opening the mobile menu must reveal the bar. */
		      if (burger) burger.addEventListener('click', function(){ setHidden(false); });
		      onScroll();   /* set the correct initial state (e.g. restored scroll) */
		    }());
	}

	function uewInit( scope ) {
		var context = scope && scope.length ? scope[ 0 ] : ( scope || document );
		var root = context.querySelector ? context.querySelector( ROOT_SELECTOR ) : null;

		if ( ! root && context !== document && context.matches && context.matches( ROOT_SELECTOR ) ) {
			root = context;
		}
		if ( ! root ) {
			root = document.querySelector( ROOT_SELECTOR );
		}
		if ( ! root ) {
			return;
		}
		if ( root && root.getAttribute( 'data-uew-ready' ) === '1' ) {
			return;
		}
		if ( root ) {
			root.setAttribute( 'data-uew-ready', '1' );
		}

		uewRun();
	}

	function uewRegister() {
		if ( ! window.elementorFrontend || ! window.elementorFrontend.hooks ) {
			return false;
		}
		window.elementorFrontend.hooks.addAction( 'frontend/element_ready/' + WIDGET_NAME + '.default', uewInit );
		return true;
	}

	if ( ! uewRegister() ) {
		// Elementor fires this through jQuery, not as a native DOM event, so a
		// plain addEventListener would never hear it.
		if ( window.jQuery ) {
			window.jQuery( window ).on( 'elementor/frontend/init', uewRegister );
		} else {
			window.addEventListener( 'elementor/frontend/init', uewRegister );
		}
	}

	// Plain page load (and any context where Elementor's frontend never boots).
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', function () {
			uewInit( document );
		} );
	} else {
		uewInit( document );
	}
}() );
